EmberforgeJournalLore = {
    [34] =
        "Stormwind Stockade is a closely guarded prison built beneath the canals of " ..
        "Stormwind City. Warden Thelwater keeps watch over the stockade and the " ..
        "highly dangerous criminals who call it home. Recently, the inmates revolted, " ..
        "overthrowing their guards and plunging the prison into a state of " ..
        "pandemonium.",
    [43] =
        "Years ago, the famed druid Naralex and his followers descended into the " ..
        "shadowy Wailing Caverns, named for the mournful cry one hears when steam " ..
        "bursts from the cave system's fissures. Naralex planned to use the " ..
        "underground springs to restore lushness to the arid Barrens. But upon " ..
        "entering the Emerald Dream, he saw his vision of regrowth turn into a waking " ..
        "nightmare, one that has plagued the caverns ever since.",
    [47] =
        "Legends state that where the demigod Agamaggan fell, his blood gave rise to " ..
        "great masses of thorny vines. Many quilboar have taken up residence in the " ..
        "largest cluster of giant thorns, the Razorfen, which they revere as " ..
        "Agamaggan's resting place. Recently, scouts have reported seeing undead " ..
        "milling about the region, engendering fears that the dreaded Scourge may be " ..
        "moving to conquer Kalimdor.",
    [48] =
        "Once dedicated to the night elves' goddess Elune, Blackfathom Deeps was " ..
        "thought to have been destroyed during the Sundering, lost beneath the ocean. " ..
        "Millennia later, members of the Twilight's Hammer cult were drawn to the " ..
        "temple by whispers and foul dreams. After sacrificing untold numbers of " ..
        "innocents, the cult was rewarded with a new task: to protect one of the Old " ..
        "Gods' most cherished creatures, a pet that is still in need of nurturing " ..
        "before he can unleash his dark powers on the world.",
    [70] =
        "Uldaman is an ancient titan vault buried deep within the earth. It is said " ..
        "the titans sealed away a failed experiment there and then moved on to a new " ..
        "project, related to the genesis of the dwarves. Tales of a fabled treasure " ..
        "containing great knowledge have enticed would-be treasure hunters to dig " ..
        "deeper into the secrets of Uldaman, a task made perilous by the presence of " ..
        "stone defenders, savage troggs, Dark Iron invaders, and other dangers " ..
        "lurking in the lost city.",
    [90] =
        "Built deep within the mountains of Dun Morogh, the wondrous city of " ..
        "Gnomeregan was a testament to the gnomes' intelligence and industry. But " ..
        "when the capital was invaded by troggs, the gnomish high tinker was betrayed " ..
        "by his advisor Sicco Thermaplugg. As a result, Gnomeregan was irradiated, " ..
        "and most of its inhabitants slain. The surviving gnomes fled, vowing to " ..
        "return someday and retake their home.",
    [109] =
        "Thousands of years ago, the Gurubashi empire was plunged into a civil war by " ..
        "a powerful sect of priests, the Atal'ai, who sought to summon to Azeroth an " ..
        "avatar of their god of blood, Hakkar the Soulflayer. The Gurubashi people " ..
        "exiled the Atal'ai to the Swamp of Sorrows, where the priests built the " ..
        "Temple of Atal'Hakkar. Ysera, Aspect of the green dragonflight, sank the " ..
        "temple beneath the swamp and assigned wardens to ensure that the summoning " ..
        "rituals never be performed again.",
    [129] =
        "Legends state that where the demigod Agamaggan fell, his blood gave rise to " ..
        "great masses of thorny vines. Many quilboar have taken up residence in the " ..
        "largest cluster of giant thorns, the Razorfen, which they revere as " ..
        "Agamaggan's resting place. Recently, scouts have reported seeing undead " ..
        "milling about the region, engendering fears that the dreaded Scourge may be " ..
        "moving to conquer Kalimdor.",
    [189] =
        "The Crusade's fanatical leaders direct their followers from the Scarlet " ..
        "Cathedral, at the heart of the monastery grounds. This heavily guarded " ..
        "location functions as the order's headquarters, and some of the most zealous " ..
        "and intolerant crusaders roam the halls of this once-hallowed place.",
    [209] =
        "Zul'Farrak was once the shining jewel of Tanaris, ferociously protected by " ..
        "the cunning Sandfury tribe. Despite the trolls' tenacity, this isolated " ..
        "group was forced to surrender much of its territory throughout history. Now, " ..
        "it appears that Zul'Farrak's inhabitants are creating a horrific army of " ..
        "undead trolls to conquer the surrounding region. Other disturbing rumors " ..
        "tell of an ancient creature sleeping within the city--one that, if awakened, " ..
        "will rain death and destruction across Tanaris.",
    [229] =
        "This imposing fortress, carved into the fiery core of Blackrock Mountain, " ..
        "represented the might of the Dark Iron clan for centuries. More recently, " ..
        "the black dragon Nefarian and his spawn seized the keep's upper spire and " ..
        "ignited a brutal war against the dwarves. The draconic armies have since " ..
        "allied with Warchief Rend Blackhand and his false Horde. This combined force " ..
        "lords over the spire, conducting horrific experiments to bolster its ranks " ..
        "while plotting the meddlesome Dark Irons' downfall.",
    [230] =
        "The smoldering Blackrock Depths are home to the Dark Iron dwarves and their " ..
        "emperor, Dagran Thaurissan. Like his predecessors, he serves under the iron " ..
        "rule of Ragnaros the Firelord, a merciless being summoned into the world " ..
        "centuries ago. The presence of chaotic elementals has attracted Twilight's " ..
        "Hammer cultists to the mountain domain. Along with Ragnaros' servants, they " ..
        "have pushed the dwarves toward increasingly destructive ends that could soon " ..
        "spell doom for all of Azeroth.",
    [269] =
        "Deep within the Caverns of Time, the brooding dragon Nozdormu has awakened. " ..
        "Since the world was young, the bronze dragonflight has safeguarded the " ..
        "winding labyrinth, monitoring the shifting timeways to ensure that the " ..
        "delicate balance of time is upheld.",
    [289] =
        "Individuals seeking to master the powers of undeath know well of " ..
        "Scholomance, the infamous school of necromancy located in the dark and " ..
        "foreboding crypts beneath Caer Darrow. In recent years, several of the " ..
        "instructors have changed, but the institution remains under the control of " ..
        "Darkmaster Gandling, a particularly sadistic and insidious practitioner of " ..
        "necromantic magic.",
    [329] =
        "Stratholme was once the jewel of northern Lordaeron, but today it is " ..
        "remembered for its harrowing fall to ruin. It was here that Prince Arthas " ..
        "turned his back on the noble paladin Uther Lightbringer, slaughtering " ..
        "countless residents believed to be infected with the horrific plague of " ..
        "undeath. Ever since, cursed Stratholme has been marred by death, betrayal, " ..
        "and hopelessness.",
    [349] =
        "According to legend, Zaetar, son of Cenarius, and the earth elemental " ..
        "princess Theradras begot the barbaric centaur race. Shortly after the " ..
        "centaur's creation, the ruthless creatures murdered their father. The " ..
        "grief-stricken Theradras is said to have trapped her lover's spirit within " ..
        "Maraudon, corrupting the region. Now, vicious centaur ghosts and twisted " ..
        "elemental minions roam every corner of the sprawling caves.",
    [389] =
        "Ragefire Chasm extends deep below the city of Orgrimmar. Barbaric troggs and " ..
        "devious Searing Blade cultists once plagued the volcanic caves, but now a " ..
        "new threat has emerged: dark shaman. Although Warchief Garrosh Hellscream " ..
        "recently called on a number of shaman to use the elements as weapons against " ..
        "the Alliance, the chasm's current inhabitants appear to be renegades. " ..
        "Reports have surfaced that these shadowy figures are amassing a blistering " ..
        "army that could wreak havoc if unleashed upon Orgrimmar.",
    [429] =
        "Built thousands of years ago to house the kaldorei's arcane secrets, the " ..
        "formerly great city of Eldre'Thalas now lies in ruin, writhing with warped, " ..
        "twisted forces. Competing covens once fought for control of Dire Maul's " ..
        "corrupted energy, but they have since settled into uneasy truces, choosing " ..
        "to exploit the power within their own territories rather than continue to " ..
        "battle over the entire complex.",
    [540] =
        "At the heart of Outland's barren Hellfire Peninsula stands Hellfire Citadel, " ..
        "a nearly impenetrable bastion that served as the Horde's base of operations " ..
        "throughout the First and Second Wars.",
    [542] =
        "At the heart of Outland's barren Hellfire Peninsula stands Hellfire Citadel, " ..
        "a nearly impenetrable bastion that served as the Horde's base of operations " ..
        "throughout the First and Second Wars.",
    [543] =
        "At the heart of Outland's barren Hellfire Peninsula stands Hellfire Citadel, " ..
        "a nearly impenetrable bastion that served as the Horde's base of operations " ..
        "throughout the First and Second Wars.",
    [545] =
        "Coilfang Reservoir is the name for a naga-dominated compound that lurks " ..
        "under Zangarmarsh's deepest waters. The reservoir, punctured throughout by " ..
        "massive open pipes and pistons, seems big enough to house armies - and, yet, " ..
        "its purpose isn't strictly military.",
    [546] =
        "Coilfang Reservoir is the name for a naga-dominated compound that lurks " ..
        "under Zangarmarsh's deepest waters. The reservoir, punctured throughout by " ..
        "massive open pipes and pistons, seems big enough to house armies - and, yet, " ..
        "its purpose isn't strictly military.",
    [547] =
        "Coilfang Reservoir is the name for a naga-dominated compound that lurks " ..
        "under Zangarmarsh's deepest waters. The reservoir, punctured throughout by " ..
        "massive open pipes and pistons, seems big enough to house armies - and, yet, " ..
        "its purpose isn't strictly military.",
    [552] =
        "The mighty Tempest Keep was created by the enigmatic naaru: sentient beings " ..
        "of pure energy and the sworn enemies of the Burning Legion. In addition to " ..
        "serving as a base of operations for the naaru, the structure itself " ..
        "possesses the technology to teleport through alternate dimensions, traveling " ..
        "from one location to another in the blink of an eye.",
    [553] =
        "The mighty Tempest Keep was created by the enigmatic naaru: sentient beings " ..
        "of pure energy and the sworn enemies of the Burning Legion. In addition to " ..
        "serving as a base of operations for the naaru, the structure itself " ..
        "possesses the technology to teleport through alternate dimensions, traveling " ..
        "from one location to another in the blink of an eye.",
    [554] =
        "The mighty Tempest Keep was created by the enigmatic naaru: sentient beings " ..
        "of pure energy and the sworn enemies of the Burning Legion. In addition to " ..
        "serving as a base of operations for the naaru, the structure itself " ..
        "possesses the technology to teleport through alternate dimensions, traveling " ..
        "from one location to another in the blink of an eye.",
    [555] =
        "The original exiles on Draenor found death to be an unsettling and " ..
        "unfortunate consequence of life, and so the draenei hid their dead away in " ..
        "the subterranean grave-city of Auchindoun, a labyrinthine marvel located " ..
        "beneath the forests of Terokkar.",
    [556] =
        "The original exiles on Draenor found death to be an unsettling and " ..
        "unfortunate consequence of life, and so the draenei hid their dead away in " ..
        "the subterranean grave-city of Auchindoun, a labyrinthine marvel located " ..
        "beneath the forests of Terokkar.",
    [557] =
        "The original exiles on Draenor found death to be an unsettling and " ..
        "unfortunate consequence of life, and so the draenei hid their dead away in " ..
        "the subterranean grave-city of Auchindoun, a labyrinthine marvel located " ..
        "beneath the forests of Terokkar.",
    [558] =
        "The original exiles on Draenor found death to be an unsettling and " ..
        "unfortunate consequence of life, and so the draenei hid their dead away in " ..
        "the subterranean grave-city of Auchindoun, a labyrinthine marvel located " ..
        "beneath the forests of Terokkar.",
    [560] =
        "Deep within the Caverns of Time, the brooding dragon Nozdormu has awakened. " ..
        "Since the world was young, the bronze dragonflight has safeguarded the " ..
        "winding labyrinth, monitoring the shifting timeways to ensure that the " ..
        "delicate balance of time is upheld.",
    [568] =
        "Echoes of unfulfilled vengeance linger in the one-time capital of the Amani " ..
        "tribe, Zul'Aman. Though the Amani trolls answered their warlord's call to " ..
        "arms, Zul'jin was denied his goal of restoring the empire to its former " ..
        "glory. Where he failed, the Zandalar tribe will succeed. Left unchecked, the " ..
        "united tribes will reclaim their lands and savor a merciless retribution.",
    [574] =
        "Utgarde Keep was long thought to be abandoned, a relic of a lost " ..
        "civilization among the central cliffs of the Howling Fjord. Yet in recent " ..
        "days something has roused the fortress' slumbering residents, the vrykul.",
    [575] =
        "Utgarde Keep was long thought to be abandoned, a relic of a lost " ..
        "civilization among the central cliffs of the Howling Fjord. Yet in recent " ..
        "days something has roused the fortress' slumbering residents, the vrykul.",
    [576] =
        "In order to reestablish his dominance over magic, the blue Dragon Aspect, " ..
        "Malygos, has launched a ruthless campaign to sever the link between mortals " ..
        "and the arcane energies coursing through Azeroth. To this end, his blue " ..
        "dragonflight is redirecting the ley lines of the world to the Nexus, " ..
        "Malygos' towering lair.",
    [578] =
        "In order to reestablish his dominance over magic, the blue Dragon Aspect, " ..
        "Malygos, has launched a ruthless campaign to sever the link between mortals " ..
        "and the arcane energies coursing through Azeroth. To this end, his blue " ..
        "dragonflight is redirecting the ley lines of the world to the Nexus, " ..
        "Malygos' towering lair.",
    [585] =
        "After his defeat in Tempest Keep, Kael'thas Sunstrider publicly revealed his " ..
        "alliance with the ruthless Burning Legion. Intent upon summoning the demon " ..
        "lord Kil'jaeden, Kael'thas has returned to the Isle of Quel'Danas to make " ..
        "the final preparations for his master's arrival.",
    [595] =
        "Deep within the Caverns of Time, the brooding dragon Nozdormu has awakened. " ..
        "Since the world was young, the bronze dragonflight has safeguarded the " ..
        "winding labyrinth, monitoring the shifting timeways to ensure that the " ..
        "delicate balance of time is upheld.",
    [599] =
        "Upon departing Azeroth, the titans entrusted loyal protectors with " ..
        "safeguarding Ulduar, an enigmatic city nestled in the mountains of the Storm " ..
        "Peaks. Designated supreme among his brethren was the guardian known as " ..
        "Loken, but with the power of the titan complex in his hands, he turned to " ..
        "darkness and plunged the region into chaos.",
    [600] =
        "Drak'Tharon Keep once served the Drakkari trolls as a formidable outpost at " ..
        "the edge of their kingdom, Zul'Drak, but a recent Scourge invasion has " ..
        "delivered the fortress into the Lich King's hands. The keep's fallen " ..
        "defenders are now the Lich King's undead minions, and they are advancing " ..
        "into the heart of Drakkari territory.",
    [601] =
        "Azjol-Nerub was an empire of great strength when the Lich King arrived in " ..
        "Northrend. Despite ferocious resistance, however, Scourge forces managed to " ..
        "overtake the subterranean kingdom and slaughter its inhabitants, the " ..
        "nerubians. Scarred by years of war and abandonment, this vast domain is now " ..
        "occupied on two fronts.",
    [602] =
        "Upon departing Azeroth, the titans entrusted loyal protectors with " ..
        "safeguarding Ulduar, an enigmatic city nestled in the mountains of the Storm " ..
        "Peaks. Designated supreme among his brethren was the guardian known as " ..
        "Loken, but with the power of the titan complex in his hands, he turned to " ..
        "darkness and plunged the region into chaos.",
    [604] =
        "Desperate to save their kingdom from collapse, the trolls of Zul'Drak have " ..
        "turned on their ancient gods. The wild deities are now considered a source " ..
        "of untapped power, their potent blood providing the means to repel the Lich " ..
        "King's minions, who have overtaken parts of the troll nation. Heroes have " ..
        "recently journeyed to the beleaguered region to strike at the savage " ..
        "Drakkari and their maddened prophets.",
    [608] =
        "Among the ornate spires and enchanted streets of Dalaran, a dark presence " ..
        "stirs within the mighty walls of the Violet Hold. Long used to restrain " ..
        "threats to the city, the tower holds row upon row of deadly inmates, and it " ..
        "has been diligently watched over by the Kirin Tor. However, a sudden assault " ..
        "has tested the integrity of the hold, putting at risk the safety of everyone " ..
        "outside the prison's walls.",
    [619] =
        "Azjol-Nerub was an empire of great strength when the Lich King arrived in " ..
        "Northrend. Despite ferocious resistance, however, Scourge forces managed to " ..
        "overtake the subterranean kingdom and slaughter its inhabitants, the " ..
        "nerubians. Scarred by years of war and abandonment, this vast domain is now " ..
        "occupied on two fronts.",
    [632] =
        "For many years, champions among the races of Azeroth have stood against the " ..
        "Lich King only to be slaughtered mercilessly and forced to serve in his army " ..
        "of undead horrors. In his ongoing struggle to stop the Lich King, Tirion " ..
        "Fordring of the Argent Crusade has joined forces with Darion Mograine of the " ..
        "Knights of the Ebon Blade in order to assault Icecrown Citadel with a " ..
        "unified army called the Ashen Verdict.",
    [650] =
        "Clouds blanket the skies of Icecrown and heroes gather beneath battle-worn " ..
        "banners in preparation for the coming storm. They say that even the darkest " ..
        "cloud has a silver lining. It is this hope that drives the men and women of " ..
        "the Argent Crusade: hope that the Light will see them through these trying " ..
        "times, hope that good will triumph over evil, hope that a hero blessed by " ..
        "the Light will come forth to put an end to the Lich King's dark reign.",
    [658] =
        "For many years, champions among the races of Azeroth have stood against the " ..
        "Lich King only to be slaughtered mercilessly and forced to serve in his army " ..
        "of undead horrors. In his ongoing struggle to stop the Lich King, Tirion " ..
        "Fordring of the Argent Crusade has joined forces with Darion Mograine of the " ..
        "Knights of the Ebon Blade in order to assault Icecrown Citadel with a " ..
        "unified army called the Ashen Verdict.",
    [668] =
        "For many years, champions among the races of Azeroth have stood against the " ..
        "Lich King only to be slaughtered mercilessly and forced to serve in his army " ..
        "of undead horrors. In his ongoing struggle to stop the Lich King, Tirion " ..
        "Fordring of the Argent Crusade has joined forces with Darion Mograine of the " ..
        "Knights of the Ebon Blade in order to assault Icecrown Citadel with a " ..
        "unified army called the Ashen Verdict.",
}
