EmberforgeJournalBosses = {
    [34] = {
        ["hogger"] = {
            d =
                "Convict #SC55: Hogger \n\nCharges: Too many to list here \n\nImprisoning the " ..
                "Riverpaw leader has come at a high cost, including the partial blinding of " ..
                "the warden. Fearing that Hogger might escape, Thelwater has authorized the " ..
                "gnoll's termination with extreme prejudice.",
            p = "UI-EJ-BOSS-Hogger",
            o = 1,
            s = {
                {
                    t = "Vicious Slice",
                    b =
                        "Hogger slices his target, inflicting Physical damage instantly and an " ..
                        "additional 5 to 6% of the targets maximum health every 2 seconds for 6 sec.",
                    i = "Ability_Warrior_PunishingBlow",
                },
                {
                    t = "Maddening Call",
                    b =
                        "Hogger unleashes a maddening call, inflicting 114 to 126 Physical damage to " ..
                        "all players within 30 yards and reduces their melee attack, ranged attack " ..
                        "and casting speed by 60 to 59% for 5 sec.",
                    i = "INV_Misc_Head_Gnoll_01",
                    f = 64,
                },
                {
                    t = "Enrage",
                    b =
                        "When Hogger reaches 30% remaining health, he enrages, increasing Physical " ..
                        "damage dealt by 10 to 11% and melee attack speed by 30 to 31%.",
                    i = "Spell_Shadow_UnholyFrenzy",
                    f = 2048,
                },
            },
        },
        ["lordoverheat"] = {
            d =
                "Convict #NA: Lord Overheat \n\nCharges: Homicide (multiple counts) \n\nThe " ..
                "natural disasters wrought by the Cataclysm caused elementals to erupt into " ..
                "the prison complex, slaughtering half of the inmates upon arrival. Removing " ..
                "these incensed threats is imperative to restoring order to the stockade.",
            p = "UI-EJ-BOSS-Lord Overheat",
            o = 2,
            s = {
                {
                    t = "Rain of Fire",
                    b =
                        "Lord Overheat calls down a molten rain, inflicting Fire damage to all " ..
                        "players in a 5 yard area for 9 sec.",
                    i = "Spell_Shadow_RainOfFire",
                },
                {
                    t = "Fireball",
                    b = "Lord Overheat inflicts Fire damage to his current target.",
                    i = "Spell_Fire_FlameBolt",
                },
                {
                    t = "Overheat",
                    b =
                        "Lord Overheat burns a random player, inflicting 50 to 51 Fire damage and an " ..
                        "additional 50 to 51 Fire damage every 3 seconds for 9 sec.",
                    i = "Spell_Fire_Burnout",
                    f = 128,
                },
            },
        },
        ["randolphmoloch"] = {
            d =
                "Convict #AC317: Randolph Moloch \n\nCharges: Embezzlement, fraud, theft, and " ..
                "homicide \n\nMoloch has been identified as the ringleader of the prison " ..
                "revolt. Given his connections to the House of Nobles, however, the use of " ..
                "lethal force to subdue this convict is not authorized.",
            p = "UI-EJ-BOSS-Randolph Moloch",
            o = 3,
            s = {
                {
                    t = "Wildly Stabbing",
                    b =
                        "Randolph Moloch stabs wildly, attacking every 0.25 seconds but his chance to " ..
                        "hit is reduced by 35 to 34%.",
                    i = "Ability_Warrior_Rampage",
                },
                {
                    t = "Sweep",
                    b =
                        "Randolph Moloch inflicts Physical damage to his current target and their " ..
                        "closest ally.",
                    i = "Ability_Warrior_Cleave",
                },
                {
                    t = "Vanish",
                    b =
                        "When Randolph Moloch reaches between 70-60% and 40-30% remaining health, he " ..
                        "vanishes from sight and reappears behind a random player, attacking them.",
                    i = "Ability_Stealth",
                },
            },
        },
    },
    [43] = {
        ["kresh"] = {
            d =
                "An ancient resident of the Wailing Caverns, this giant turtle wanders the " ..
                "underground caves, his resilient mind unaffected by Naralex's relentless " ..
                "nightmares. Don't be fooled by his happy disposition; Kresh has thwarted " ..
                "many adventurers who longed to steal his massive shell.",
            p = "UI-EJ-BOSS-Kresh",
            o = 4,
            s = {
                {
                    t = "Crushing Bite",
                    b = "Kresh bites his current target, reducing their armor by 10 to 9% for 20 sec.",
                    i = "INV_Misc_Bone_09",
                },
            },
        },
        ["ladyanacondra"] = {
            d =
                "Scarletleaf was the first to volunteer for Naralex's self-appointed mission " ..
                "to the Barrens. After her master's nightmare shattered her mind, the young " ..
                "acolyte cast aside her name, now envisioning a sinister reptilian future for " ..
                "Azeroth.",
            p = "UI-EJ-BOSS-Lady Anacondra",
            o = 1,
            s = {
                {
                    t = "Lightning Bolt",
                    b =
                        "Lady Anacondra hurls a bolt of lightning at her current target, inflicting " ..
                        "Nature damage.",
                    i = "Spell_Nature_Lightning",
                    f = 64,
                },
                {
                    t = "Druid's Slumber",
                    b =
                        "Lady Anacondra puts a player to sleep for 15 sec. Any hostile action will " ..
                        "awaken the target.",
                    i = "Spell_Nature_Sleep",
                    f = 192,
                },
                {
                    t = "Thorns Aura",
                    b =
                        "Lady Anacondra's thorns inflict Nature damage to any player that melee " ..
                        "attack her.",
                    i = "Spell_Nature_Thorns",
                },
                {
                    t = "Healing Touch",
                    b = "Lady Anacondra heals an ally.",
                    i = "Spell_Nature_HealingTouch",
                    f = 64,
                },
            },
        },
        ["lordcobrahn"] = {
            d =
                "Jarlaxla's skill at harnessing animal forms earned him renown among the " ..
                "druids of the Cenarion Circle. However, the Wailing Caverns' corruption " ..
                "twisted his unique abilities. Now, Jarlaxla has perfected a deadly " ..
                "serpentine form, renaming himself Cobrahn to reflect his vicious newfound " ..
                "power.",
            p = "UI-EJ-BOSS-Lord Cobrahn",
            o = 3,
            s = {
                {
                    t = "Lord Cobrahn: The Fanglord",
                    b =
                        "Lord Cobrahn engages his foes in his Night Elf form, testing their strength " ..
                        "in battle.",
                },
                {
                    t = "Lightning Bolt",
                    b =
                        "Lord Cobrahn hurls a bolt of lightning at his current target, inflicting " ..
                        "Nature damage.",
                    i = "Spell_Nature_Lightning",
                    f = 64,
                    l = 1,
                },
                {
                    t = "Druid's Slumber",
                    b =
                        "Lord Cobrahn puts a player to sleep for 15 sec. Any hostile action will " ..
                        "awaken the target.",
                    i = "Spell_Nature_Sleep",
                    f = 192,
                    l = 1,
                },
                {
                    t = "Healing Touch",
                    b = "Lord Cobrahn heals an ally.",
                    i = "Spell_Nature_HealingTouch",
                    f = 64,
                    l = 1,
                },
                {
                    t = "Lord Cobrahn: The Serpent",
                    b = "When Lord Cobrahn reaches 45% remaining health, he transforms into a serpent.",
                },
                {
                    t = "Serpent Form",
                    b =
                        "Lord Cobrahn transforms into a serpent, increasing his melee damage by 50 " ..
                        "but increasing the time between his attacks by 43%.",
                    i = "Spell_Nature_GuardianWard",
                    l = 1,
                },
                {
                    t = "Poison",
                    b =
                        "Lord Cobrahn poisons a player, inflicting Nature damage every 3 seconds for " ..
                        "30 sec.",
                    i = "Spell_Nature_CorrosiveBreath",
                    f = 512,
                    l = 1,
                },
            },
        },
        ["lordpythas"] = {
            d =
                "A childhood friend of Naralex, the warrior Aryn was a quick study in " ..
                "druidism. Despite his training, the acolyte was defenseless against the " ..
                "corruption that would strip away his sanity. Aryn has taken on the name " ..
                "Pythas, combining his impressive melee prowess with his druidic arsenal to " ..
                "vanquish intruders.",
            p = "UI-EJ-BOSS-Lord Pythas",
            o = 2,
            s = {
                {
                    t = "Lightning Bolt",
                    b =
                        "Lord Pythas hurls a bolt of lightning at his current target, inflicting " ..
                        "Nature damage.",
                    i = "Spell_Nature_Lightning",
                    f = 64,
                },
                {
                    t = "Druid's Slumber",
                    b =
                        "Lord Pythas puts a player to sleep for 15 sec. Any hostile action will " ..
