                    i = "Spell_Nature_Sleep",
                    f = 192,
                },
                {
                    t = "Healing Touch",
                    b = "Lord Pythas heals an ally.",
                    i = "Spell_Nature_HealingTouch",
                    f = 64,
                },
                {
                    t = "Thunderclap",
                    b =
                        "Lord Pythas inflicts Nature damage to all players within 10 yards, " ..
                        "increasing the time between their attacks by 43% and slowing their movement " ..
                        "speed by 40% for 10 sec.",
                    i = "Spell_Nature_ThunderClap",
                    f = 128,
                },
            },
        },
        ["lordserpentis"] = {
            d =
                "The Druids of the Fang's leader was once Naralex's finest student. His " ..
                "tragic downfall stemmed from his desire to become a shan'do, or \"honored " ..
                "teacher,\" like Naralex. As insanity took root, Serpentis rallied his " ..
                "brethren to his side and formed the Druids of the Fang.",
            p = "UI-EJ-BOSS-Lord Serpentis",
            o = 6,
            s = {
                {
                    t = "Lightning Bolt",
                    b =
                        "Lord Serpentis hurls a bolt of lightning at his current target, inflicting " ..
                        "Nature damage.",
                    i = "Spell_Nature_Lightning",
                    f = 64,
                },
                {
                    t = "Druid's Slumber",
                    b =
                        "Lord Serpentis puts a player to sleep for 15 sec. Any hostile action will " ..
                        "awaken the target.",
                    i = "Spell_Nature_Sleep",
                    f = 192,
                },
                {
                    t = "Healing Touch",
                    b = "Lord Serpentis heals an ally.",
                    i = "Spell_Nature_HealingTouch",
                    f = 64,
                },
            },
        },
        ["mutanusthedevourer"] = {
            d =
                "From the darkest corners of Naralex's twisted mind, the corruption plaguing " ..
                "the Emerald Dream has manifested in the form of the druid's worst enemy: " ..
                "murlocs. The aberration known as Mutanus has come to the waking world to " ..
                "devour any who seek to liberate Naralex from the Nightmare's clutches.",
            p = "UI-EJ-BOSS-Mutanus the Devourer",
            o = 8,
            s = {
                {
                    t = "Naralex's Nightmare",
                    b =
