                        "will awaken the target.",
                    i = "Spell_Nature_Sleep",
                    f = 192,
                },
                {
                    t = "Terrify",
                    b = "Mutanus the Devourer terrifies a player, causing them to flee in fear for 4 sec.",
                    i = "Ability_Physical_Taunt",
                    f = 128,
                },
                {
                    t = "Thundercrack",
                    b =
                        "Mutanus the Devourer inflicts Nature damage to all players within 10 yards, " ..
                        "stunning them for 2.5 sec.",
                    i = "Spell_Nature_ThunderClap",
