        },
        ["skum"] = {
            d =
                "Skum first journeyed to the Wailing Caverns for relief from the Barrens' " ..
                "hostile environment. Like many of the caves' other inhabitants, he quickly " ..
                "succumbed to corruption. His veins now pulse with dark energies that have " ..
                "transformed him into a mighty and ruthless beast beyond redemption.",
            p = "UI-EJ-BOSS-Skum",
            o = 5,
            s = {
                {
                    t = "Chained Bolt",
                    b =
                        "Skum strikes a players with a lightning bolt that arcs to other nearby " ..
                        "players, inflicting Nature damage. Chain bolt affects up to 3 yards.",
                    i = "Spell_Nature_ChainLightning",
                    f = 64,
                },
            },
        },
        ["verdantheeverliving"] = {
            d =
                "Little is known about this creature prior to Naralex's arrival at the " ..
                "Wailing Caverns. Thought to be the caves' original guardian, Verdan the " ..
                "Everliving could not escape the corruption that befell its home. Verdan is " ..
                "allied with the insane druids and maintains its vigil against those who " ..
                "trespass into its domain.",
            p = "UI-EJ-BOSS-Verdan the Everliving",
            o = 7,
            s = {
                {
                    t = "Grasping Vines",
                    b =
                        "Verdan the Everliving grasps all players within 10 yards in vines, " ..
                        "inflicting Physical damage, knocking them down and immobilizing them for 10 " ..
                        "sec.",
                    i = "Spell_Nature_StrangleVines",
                },
            },
        },
    },
    [47] = {
        ["agathelostheraging"] = {
            d =
                "Boars are revered within quilboar culture, and particularly large and " ..
                "tenacious ones are seen as a favor from Agamaggan. Already a powerful " ..
                "creature, Agathelos has been fed Kraul bat guano, which produces a maddening " ..
                "effect, resulting in increased stamina and strength. The Death's Head plan " ..
                "to utilize Agathelos as a powerful weapon to crush all who oppose them.",
            p = "UI-EJ-BOSS-Agathelos the Raging",
            o = 4,
            s = {
                {
                    t = "Rushing Charge",
                    b =
                        "Agathelos the Raging rushes towards his target, increasing his movement " ..
