        ["charlgarazorflank"] = {
            d =
                "The leader (or \"crone\") of the Death's Head and Razorfen tribes is Charlga " ..
                "Razorflank, a quilboar who experienced an unparalleled and meteoric rise to " ..
                "power. Her aim is to resurrect the demigod Agamaggan, but the dark and " ..
                "violent rituals Charlga and her minions perform are quite at odds with the " ..
                "Ancient's noble and protective demeanor.",
            p = "UI-EJ-BOSS-Charlga Razorflank",
            o = 5,
            s = {
                {
                    t = "Chain Bolt",
                    b =
                        "Charlga Razorflank strikes her target with a lightning bolt that arcs to " ..
