        },
        ["deathspeakerjargba"] = {
            d =
                "The Death Speakers of the Death's Head tribe serve two functions: to " ..
                "disseminate propaganda and to discipline those who refuse to obey Charlga " ..
                "Razorflank and, by extension, her mysterious new allies. Jargba has made a " ..
                "name for himself among the Death Speakers by dominating the very minds of " ..
                "dissidents, forcing them to accept the will of their leaders.",
            p = "UI-EJ-BOSS-Death Speaker Jargba",
            o = 1,
            s = {
                {
                    t = "Shadow Bolt",
