        },
        ["overlordramtusk"] = {
            d =
                "The commander of the Death's Head military forces, Overlord Ramtusk is a " ..
                "massive aging quilboar whose thick hide bears the scars of many battles with " ..
                "centaur, harpies, orcs, and even tauren. Rather than being slowed by his " ..
