    [48] = {
        ["akumai"] = {
            d =
                "Aku'mai, an ancient evil, carries within him a small measure of the Old " ..
                "Gods' power. This three-headed hydra is greatly feared for his mindless " ..
                "savagery and insatiable hunger for living flesh, but the Twilight's Hammer " ..
                "worships him as a divine sign that the Old Gods will soon return.",
            p = "UI-EJ-BOSS-Akumai",
            o = 6,
            s = {
                {
                    t = "Poison Cloud",
                    b =
                        "Aku'mai inflicts Nature damage to all players within 8 yards every 5 seconds " ..
                        "for 45 sec.",
                    i = "Spell_Nature_Regenerate",
                },
                {
                    t = "Frenzied Rage",
                    b = "Aku'mai attacks 75% faster but deals 15 less damage for 5 sec.",
                    i = "Spell_Shadow_UnholyFrenzy",
                },
            },
        },
        ["gelihast"] = {
            d =
                "The Old Gods called, and Gelihast answered, forcing his way into Blackfathom " ..
                "Deeps and slaughtering nearly a dozen surprised Twilight's Hammer cultists " ..
                "with his twin swords. Impressed by his ferocity and brutality, the cult " ..
                "allowed him to stay, and he built his own shrine to offer sacrifices and " ..
                "receive blessings from the ominous presence in the temple ruins.",
            p = "UI-EJ-BOSS-Gelihast",
            o = 3,
            s = {
                {
                    t = "Mrrrrrglglglglrrrr!",
                    b = "Gelihast wields a sword in each hand.",
                },
                {
                    t = "Net",
                    b = "Gelihast throws his net at a player. Netted players are rooted for 2 sec.",
                    i = "Ability_Ensnare",
                },
            },
        },
        ["ghamoora"] = {
            d =
                "When the Twilight's Hammer cult arrived, its followers roused and imprisoned " ..
                "one of the last peaceful creatures living in Elune's temple. The cult " ..
                "delighted in tormenting the giant turtle for years, flaying its mind and " ..
                "body until it succumbed to madness. Naming the beast Ghamoo-Ra, the cultists " ..
                "trained it to attack outsiders and defend the Old Gods' shrine.",
            p = "UI-EJ-BOSS-Ghamoo Ra",
            o = 1,
            s = {
                {
                    t = "Trample",
                    b = "Ghamoo-Ra inflicts Physical damage to all players within 10 yards.",
                    i = "Spell_Nature_NaturesWrath",
                },
            },
        },
        ["ladysarevess"] = {
            d =
                "The Twilight's Hammer granted Lady Sarevess her own private cove within " ..
                "Blackfathom Deeps, continuously sending her fresh sacrifices. The cultists " ..
                "hope that her rituals and research will result in magical protection that " ..
                "will allow them to worship the terrifying hydra at the deeps' core without " ..
                "fear of becoming his next meal.",
            p = "UI-EJ-BOSS-Lady Sarevess",
            o = 2,
            s = {
                {
                    t = "Forked Lightning",
                    b = "Lady Sarevess inflicts Nature damage to all players in a cone in front of her.",
                    i = "Spell_Nature_ChainLightning",
                    f = 64,
                },
                {
                    t = "Slow",
                    b =
                        "Lady Sarevess slows the melee attack speed and movement speed of a player. " ..
                        "Slowed players attack and move 35% slower. This effect lasts for 10 sec.",
                    i = "Spell_Nature_Slow",
                    f = 128,
                },
                {
                    t = "Shoot",
                    b = "Lady Sarevess shoots a player for Physical damage.",
                    i = "Ability_Marksmanship",
                },
            },
        },
        ["oldserrakis"] = {
            d =
                "Many of the creatures swimming beneath the Moonshrine Ruins were killed for " ..
                "food after the Twilight's Hammer cult took up residence, but the largest " ..
                "thresher in the water proved to be uncatchable, and those who persisted in " ..
                "hunting it inevitably died in the attempt.",
            p = "UI-EJ-BOSS-Old Serrakis",
            o = 4,
            s = {
                {
                    t = "Leech Pulse",
                    b =
                        "Serra'kis leeches health from all nearby players, inflicting Shadow damage " ..
                        "and healing himself every 4 seconds.",
                    i = "Spell_Holy_SealOfSacrifice",
                },
            },
        },
        ["twilightlordkelris"] = {
            d =
                "When the cultists found a strange three-headed creature in the belly of " ..
                "Blackfathom Deeps, Twilight Lord Kelris was convinced the hydra was a herald " ..
                "of the Old Gods' return to Azeroth... and his ticket to immortality. Kelris " ..
                "personally supervises the growth of the monster, even feeding him his own " ..
                "subjects to satisfy his wild hunger.",
            p = "UI-EJ-BOSS-Twilight Lord Kelris",
            o = 5,
            s = {
                {
                    t = "Mind Blast",
                    b = "Twilight Lord Kelris inflicts Shadow damage to a player.",
                    i = "Spell_Shadow_UnholyFrenzy",
                },
                {
                    t = "Sleep",
                    b =
                        "Twilight Lord Kelris puts all players within 5 yards to sleep for 10 sec. " ..
                        "Any damage inflicted will awaken players who are asleep.",
                    i = "Spell_Nature_Sleep",
                    f = 128,
                },
            },
        },
    },
    [70] = {
        ["ancientstonekeeper"] = {
            d =
                "One of many golems that staffed and operated the great titan vault, the " ..
                "Ancient Stone Keeper was part of a small group that served as an " ..
                "intermediary between the watchers left in control of the facility and their " ..
                "many servants. With the corruption of the Obsidian Sentinel, the Ancient " ..
                "Stone Keeper is the last of its kind, performing its duty by protecting the " ..
                "secrets of the titans as best it can until its inevitable shutdown.",
            p = "UI-EJ-BOSS-Ancient Stone Keeper",
            o = 5,
            s = {
                {
                    t = "Sand Storms",
                    b =
                        "Ancient Stone Keeper summons a sand storm that moves towards a player, " ..
                        "inflicting physical damage and reducing movement speed of all players within " ..
                        "5 yards.",
                    i = "Spell_Nature_EarthBind",
                },
            },
        },
        ["archaedas"] = {
            d =
                "Deep within Uldaman is a chamber containing one of the greatest treasures of " ..
                "the titans, created by Norgannon himself. However, thus far no explorers " ..
                "have managed to gain access to the relic, for any attempt at doing so " ..
                "activates the great watcher Archaedas, an immense guardian who easily " ..
                "dispatches treasure seekers through his powerful attacks and a veritable " ..
                "army of servants. Crafted from some of the oldest, strongest stone taken " ..
                "from Uldaman's depths, Archaedas is a foe as formidable as he is ancient.",
            p = "UI-EJ-BOSS-Archaedas",
            o = 8,
            s = {
