        ["grimlok"] = {
            d =
                "In trogg society, the biggest, strongest, and most vicious trogg often " ..
                "becomes chieftain through displays of power. Grimlok is a comparative genius " ..
                "in that he has maintained control of the Stonevault troggs through " ..
