        ["ironaya"] = {
            d =
                "The titans did not construct the Uldaman complex directly, but utilized " ..
                "various servants to create its megalithic halls. The Pantheon entrusted the " ..
                "watcher Ironaya with overseeing the construction and maintenance of Uldaman, " ..
                "but as time passed, the once awe-inspiring vault fell to ruin. Within the " ..
                "map chamber, Ironaya has spent millennia in a form of stasis, analyzing the " ..
                "original master plan drawn up by Khaz'goroth and attempting to find a way to " ..
                "restore the complex to its original functionality.",
            p = "UI-EJ-BOSS-Ironaya",
            o = 3,
            s = {
                {
                    t = "Arcing Smash",
                    b =
                        "Ironaya lashes out in a vicious arc, inflicting Physical damage to all " ..
                        "enemies in front of her.",
                    i = "Ability_Warrior_Cleave",
