                {
                    t = "Knock Away",
                    b = "Ironaya inflicts Physical damage to her current target, knocking them away.",
                    i = "INV_Gauntlets_05",
                },
                {
                    t = "War Stomp",
                    b =
                        "Ironaya stomps, inflicting Physical damage to all enemies within 5 yards and " ..
                        "stunning them for 5 sec.",
                    i = "Ability_BullRush",
                },
            },
        },
        ["obsidiansentinel"] = {
            d =
                "The Obsidian Sentinel was responsible for guarding Uldaman's secrets until " ..
                "it was corrupted by an unknown force. Originally crafted from the same stone " ..
                "as the halls of Uldaman itself, this keeper has had the majority of its body " ..
                "replaced with dark glass capable of reflecting spells. Whatever was " ..
                "responsible for the Obsidian Sentinel's transformation must be incredibly " ..
                "potent, for it is not easy to alter the enchanted stone of a titan " ..
                "construct.",
            p = "UI-EJ-BOSS-Obsidian Sentinel",
            o = 4,
            s = {
                {
                    t = "Obsidian Reflection",
                    b =
                        "Obsidian Sentinel raises a reflective shield, giving it a 20% chance of " ..
                        "reflecting the next spell cast at him.",
                    i = "Spell_Shadow_Teleport",
                },
                {
                    t = "Splintered Obisian",
                    b =
                        "Obsidian Sentinel splinters, reducing its damage done by 60 and summoning an " ..
