                    i = "Spell_Shadow_Teleport",
                    l = 1,
                },
            },
        },
        ["olaf"] = {
            d =
                "Seeking fame and, more importantly, fortune, the three brothers Eric, Olaf, " ..
                "and Baelog took on a contract from the Explorers' League to delve deep into " ..
                "the halls of Uldaman and clear a path for a group of researchers. For these " ..
                "three dwarves, however, \"clearing a path\" unfortunately entailed \"getting " ..
                "hopelessly lost in an ancient labyrinth.\" Proud dwarves to the end, they " ..
                "fight to prevent the secrets of Uldaman and the Explorers' League from " ..
                "falling into the hands of the Horde.",
            p = "UI-EJ-BOSS-Baelog",
            o = 2,
            s = {
                {
                    t = "Baelog",
                    b = "Baelog favors combat, attacking with his sword and bow.",
