                    i = "Ability_Warrior_ShieldBash",
                    l = 1,
                },
            },
        },
        ["revelosh"] = {
            d =
                "Some luminaries in Ironforge's prestigious Explorers' League have theorized " ..
                "an ancestral link between their people and the troggs, and pointed towards " ..
                "the troggs' hoarding of titan artifacts as a reflection of the dwarves' own " ..
                "reverence for such wondrous devices. If that is true, the trogg known as " ..
                "Revelosh can be considered the trogg equivalent of an archaeologist, " ..
                "although any historically minded adventurers who encounter him would be more " ..
                "inclined to call him a thief.",
