    [90] = {
        ["crowdpummeler960"] = {
            d =
                "In Gnomeregan's heyday, inventors would compete for status by pitting their " ..
                "creations against one another. The mekgineer Oglethorpe Obnoticus built an " ..
                "unbeatable robot, and this earned him respect in the high tinker's court. " ..
                "Sicco Thermaplugg stole Obnoticus's blueprints and then made a giant version " ..
                "of the machine. He set his forgery loose, and the horrific results drove the " ..
                "ruling council to banish the innocent Obnoticus. The Crowd Pummeler 9-60 is " ..
                "still one of Thermaplugg's favorite (stolen) inventions.",
            p = "UI-EJ-BOSS-Crowd Pummeler 9-60",
            o = 4,
            s = {
                {
                    t = "Arcing Smash",
                    b =
                        "Crowd Pummeler 9-60 lashes out in a vicious arc, inflicting Physical damage " ..
                        "to players in front of it.",
                    i = "Ability_Warrior_Cleave",
                },
                {
                    t = "Crowd Pummel",
                    b =
                        "Crowd Pummeler 9-60 pummels players within 10 yards, inflicting Physical " ..
                        "damage and interrupting spell casting for 5 sec.",
                    i = "INV_Gauntlets_04",
                },
                {
                    t = "Trample",
                    b =
                        "Crowd Pummeler 9-60 tramples players within 10 yards, inflicting Physical " ..
                        "damage.",
                    i = "Spell_Nature_NaturesWrath",
                },
            },
        },
        ["electrocutioner6000"] = {
            d =
                "Mekgineer Thermaplugg is not a patient gnome. Rather than putting his " ..
                "inventions through a battery of tests to determine their safety and " ..
                "effectiveness, he rushes them into the field and moves on to the next " ..
                "project. The Electrocutioner 6000 was his first attempt at harnessing " ..
                "electricity as a weapon via a super-charged mechano-tank. Lieutenant Tom " ..
                "\"Sizzlepants\" Crankle, the only soldier to survive piloting the " ..
                "Electrocutioner, is now something of a hero among the leper gnomes.",
            p = "UI-EJ-BOSS-Electrocutioner 6000",
            o = 3,
            s = {
                {
                    t = "Megavolt",
                    b = "Electrocutioner 6000 inflicts Nature damage to all players in front of him.",
                    i = "Spell_Nature_ChainLightning",
                    f = 64,
                },
                {
                    t = "Shock",
                    b =
                        "Electrocutioner 6000 throws a bolt of lightning at his current target, " ..
                        "inflicting 261 to 277 Nature damage.",
                    i = "Spell_Nature_WispHeal",
                },
                {
                    t = "Chain Bolt",
                    b =
                        "Electrocutioner 6000 strikes his current target with a lightning bolt that " ..
                        "arcs to 3 nearby targets, inflicting 138 to 156 Nature damage to each " ..
                        "target.",
                    i = "Spell_Nature_ChainLightning",
                    f = 64,
                },
            },
        },
        ["grubbis"] = {
            d =
                "The radioactive gas that flooded the city was meant to anger the troggs and " ..
                "kill the gnomes, and Thermaplugg's plan was brutally effective. One trogg, " ..
                "however, reacted oddly to the substance: Grubbis grew. And grew. It was a " ..
                "side effect that Sicco had not anticipated, but he's never been one to waste " ..
                "valuable (and dangerous) resources. This giant trogg now patrols the tunnels " ..
                "of Gnomeregan. His loyal basilisk pet, Chomper, helps Grubbis sniff out gas " ..
                "leaks, tasty fungi, and even tastier intruders.",
            p = "UI-EJ-BOSS-Grubbis",
            o = 1,
            s = {
                {
                    t = "Strike",
                    b = "Grubbis inflicts Physical damage to his current target.",
                    i = "Ability_Rogue_Ambush",
                },
                {
                    t = "Chomper",
                    b = "Chomper fights alongside Grubbis.",
                },
            },
        },
        ["mekgineerthermaplugg"] = {
            d =
                "Murderer, traitor, and self-proclaimed king of the gnomes, the mekgineer " ..
                "Sicco Thermaplugg rules over the radioactive halls of Gnomeregan with a " ..
                "malfunctioning iron fist. His subjects are numerous, vicious, and insane " ..
                "enough to defend their crazed king against any intrusion from the upper " ..
                "world. It is Thermaplugg's madness that makes him so dangerous; he possesses " ..
                "the cunning to destroy everything around him, with no thought for his own " ..
                "life. There is a reason that even the monsters of Gnomeregan fear him.",
            p = "UI-EJ-BOSS-Mekgineer Thermaplugg",
            o = 5,
            s = {
                {
                    t = "Steam Blast",
                    b =
                        "Mekgineer Thermaplugg blasts his current target with steam, inflicting 21 to " ..
                        "28 Fire damage and knocking them back.",
                    i = "Spell_Fire_WindsofWoe",
                    f = 64,
                },
                {
                    t = "Pound",
                    b =
                        "Mekgineer Thermaplugg pounds his current target, inflicting Physical damage " ..
                        "and disorienting them for 2 sec.",
                    i = "Ability_GolemThunderClap",
                },
                {
                    t = "Welding Beam",
                    b =
                        "Mekgineer Thermplugg blasts his current target with a welding beam, " ..
                        "inflicting 250 Nature damage over 5 sec.",
                    i = "Spell_Nature_LightningOverload",
                    f = 64,
                },
                {
                    t = "Walking Bomb",
                    b =
                        "Mekgineer Thermaplugg activates a nearby bomb assembly, causing it to " ..
                        "periodically release Walking Bombs that attack a random player. Walking " ..
                        "Bombs will continue to spawn until the red switch on the side of the " ..
                        "assembly is activated.",
                    f = 32,
                },
                {
                    t = "Detonate",
                    b =
                        "Walking Bomb detonates when it reaches its target, inflicting 200 to 300 " ..
                        "Fire damage to all players within 10 yards.",
                    i = "Spell_Fire_SelfDestruct",
                    l = 1,
                },
            },
        },
        ["viscousfallout"] = {
            d =
                "The formerly robust and elegantly complex waterways of Gnomeregan are now an " ..
                "irradiated mess filled with toxic slime. A lone water elemental who had " ..
                "dwelt in the gnomes' aquifer became trapped in the contamination, and the " ..
                "pollution corrupted its pure form. It currently wanders the halls of " ..
                "Gnomeregan in anger and agony, a liquid embodiment of the vile poison of " ..
                "Thermaplugg's betrayal.",
            p = "UI-EJ-BOSS-Viscous Fallout",
            o = 2,
            s = {
                {
                    t = "Toxic Volley",
                    b =
                        "Viscous Fallout unleashes a volley of toxin, inflicting 56 Nature damage to " ..
                        "all players within 45 yards and 7 Nature damage every 3 seconds for 15 sec.",
                    i = "Spell_Nature_CorrosiveBreath",
                    f = 512,
                },
            },
        },
    },
    [109] = {
        ["avatarofhakkar"] = {
            d =
                "Hakkar was notorious for demanding sacrifices from his followers. Many " ..
                "millennia ago, he instructed the Atal'ai to bring forth his avatar, using " ..
                "blood ritually drained from living victims to feed him. The Atal'ai priests " ..
                "now seek to raise Hakkar's avatar with a modified version of this ritual, " ..
                "one that involves sacrificing green dragons. If the Atal'ai succeed, the " ..
                "re-emergence of Hakkar's avatar could spell doom for Azeroth.",
            p = "UI-EJ-BOSS-Avatar of Hakkar",
            o = 1,
            s = {
                {
                    t = "Cause Insanity",
                    b =
