    [129] = {
        ["amnennarthecoldbringer"] = {
            d =
                "The lich Amnennar and his forces participated in the Scourge's assault on " ..
                "Mount Hyjal during the Third War. Afterward, the Lich King instructed his " ..
                "servant to remain in Kalimdor and expand the Scourge's influence, and so " ..
                "Amnennar began plans to create a base from which to strike at Orgrimmar and " ..
                "Theramore. To that end, Amnennar has set his sights on recruiting the " ..
                "recently displaced and desperate quilboar people, promising them power over " ..
                "death so they can repel invaders in their lands.",
            p = "UI-EJ-BOSS-Amnennar the Coldbringer",
            o = 4,
            s = {
                {
                    t = "Frostbolt",
