                        "between their attacks by 25%.",
                    i = "Spell_Frost_FrostArmor02",
                },
            },
        },
        ["glutton"] = {
            d =
                "Living up to his name, this massive abomination has spent much of his time " ..
                "in Razorfen Downs gorging himself on the spoiled corpses of boars and their " ..
                "quilboar masters. The mass of rancid meat within his gut emanates a cloud of " ..
                "noxious fumes and crippling diseases, choking unfortunate adventurers who " ..
                "stray too close.",
            p = "UI-EJ-BOSS-Glutton",
            o = 3,
            s = {
                {
                    t = "Thrash",
                    b = "Glutton thrashes, attacking 2 additional times.",
                    i = "Ability_GhoulFrenzy",
                },
                {
                    t = "Disease Cloud",
                    b =
                        "A cloud of disease surrounds Glutton, inflicting 85 Nature damage to all " ..
                        "players within 5 yards every 3 seconds.",
                    i = "Spell_Nature_AbolishMagic",
                },
                {
                    t = "Frenzy",
                    b =
                        "When Glutton reaches 15% remaining health, he goes into a frenzy, increasing " ..
                        "Physical damage done by 45 and attack speed by 30%.",
                    i = "Spell_Shadow_UnholyFrenzy",
                },
            },
        },
        ["mordreshfireeye"] = {
            d =
                "Once an orc shaman sent from Orgrimmar to investigate the strange goings-on " ..
                "in Razorfen Downs, Mordresh was slain and remade into an undead servant of " ..
                "the Scourge. Deeming the elements to be unreliable, the lord of Razorfen " ..
                "Downs empowered Mordresh with blazing fel energies to sear the flesh of the " ..
                "living. In a mockery of his former calling as a spiritual leader, Mordresh " ..
                "utilizes his powers to incite lesser undead into a violent frenzy.",
            p = "UI-EJ-BOSS-Mordresh Fire Eye",
            o = 2,
            s = {
                {
                    t = "Fireball",
                    b = "Mordresh Fire Eye inflicts Fire damage to his current target.",
                    i = "Spell_Fire_FlameBolt",
                    f = 64,
