                        "enemies within 10 yards.",
                    i = "Spell_Fire_SealOfFire",
                    f = 64,
                },
            },
        },
        ["tutenkash"] = {
            d =
                "Though blinded during the War of the Spider before his conversion to " ..
                "undeath, Tuten'kash still serves the Scourge as one of its deadliest crypt " ..
                "fiend commanders. Tuten'kash compensates for his blindness by decorating his " ..
                "lair with fine, almost invisible webs that allow him to sense every footstep " ..
                "and the lightest touch, alerting him to send out minions to ambush his " ..
                "hapless prey. Strong vibrations can send him into a disoriented rage, " ..
                "drawing him from his hiding spot deep within Razorfen Downs' recesses.",
            p = "UI-EJ-BOSS-Tutenkash",
            o = 1,
            s = {
                {
                    t = "Thrash",
                    b = "Tuten'kash thrashes, attacking 2 additional times.",
