        ["chiefukorzsandscalp"] = {
            d =
                "Chief Ukorz Sandscalp is obsessed with restoring his tribe to its former " ..
                "glory. He was raised on stories of a time when trolls lorded over their " ..
                "ancient lands without interference from goblins, gnomes, pirates, ogres, and " ..
