    [229] = {
        ["generaldrakkisath"] = {
            d =
                "A cunning and ruthless strategist, Drakkisath commands Nefarian's armies in " ..
                "the war with Ragnaros. After securing victories against the Dark Irons, " ..
                "General Drakkisath's forces are positioned to drive the dwarves out of " ..
                "Blackrock Mountain once and for all.",
            p = "UI-EJ-BOSS-General Drakkisath",
            o = 14,
            s = {
