        ["gizrultheslavener"] = {
            d =
                "Very few of the Dark Horde have seen the reclusive and unpredictable Gizrul. " ..
                "The beast emerges from his shadowy den only when his mate, Halycon, calls to " ..
                "him. The two monstrous creatures have produced some of the largest--and most " ..
                "ferocious--worgs ever bred in orcish history.",
            p = "UI-EJ-BOSS-Gizrul the Slavener",
            o = 8,
            s = {
                {
