    [230] = {
        ["ambassadorflamelash"] = {
            d =
                "For his unwavering service to Ragnaros, Flamelash ascended to the rank of " ..
                "ambassador to the Dark Iron clan. This depraved being initially despised his " ..
                "dwarven allies, but he has come to respect their penchant for destruction. " ..
                "As a show of solidarity, Flamelash guards the Chamber of Enchantment, a " ..
                "sacred location used by the dwarves to empower their weaponry.",
            p = "UI-EJ-BOSS-Ambassador Flamelash",
            o = 16,
            s = {
                {
                    t = "Burning Spirit",
                    b =
                        "Burning Spirits spawn at the 7 Flame Runes located around the edge of " ..
                        "Ambassador Flamelash's room. Burning Spirits will move toward Ambassador " ..
                        "Flamelash and cast Burning Spirit.",
                    f = 32,
                },
                {
                    t = "Burning Spirit",
                    b =
                        "Burning Spirits will sacrifice themselves to give Burning Spirit to " ..
                        "Ambassador Flamelash when they get within 1 yard of him.\nBurning Spirit " ..
                        "increases the damage of Ambassador Flamelash by 30% and increases his size " ..
                        "by 6%. Burning Spirit stacks up to 50 charges.",
                    i = "Spell_Fire_Fire",
                    l = 1,
                },
                {
                    t = "Fire Blast",
                    b =
                        "Ambassador Flamelash inflicts 220 to 260 Fire damage to players he hits in " ..
                        "melee.",
                    i = "Spell_Fire_Immolation",
                },
            },
        },
        ["baelgar"] = {
            d =
