        ["emperordagranthaurissan"] = {
            d =
                "Emperor Dagran Thaurissan rules alongside Princess Moira of the rival " ..
                "Bronzebeard clan. Debate rages over whether the emperor ensorcelled his " ..
                "bride or she willingly joined him. Whatever the truth, Thaurissan's " ..
                "continued presence bodes ill for the future of his clan. So long as he " ..
                "lives, the Dark Irons will remain pawns of Ragnaros, and a dire threat to " ..
                "kingdoms throughout Azeroth.",
