        ["houndmastergrebmar"] = {
            d =
                "Grebmar Fleabeard's hounds are the only family he's ever known. Long ago, " ..
                "the orphaned dwarf began breeding canines to serve as companions and guard " ..
                "dogs. When the houndmaster isn't patrolling Blackrock Depths with his loyal " ..
                "beasts, he often treats them to the Grim Guzzler's finest Dark Iron ale.",
            p = "UI-EJ-BOSS-Houndmaster Grebmar",
