                "believe that her foul powers are tied to the spirit of her dead lover, " ..
                "Zaetar. If so, liberating the fallen keeper of the grove might be the only " ..
                "hope of cleansing Maraudon.",
            p = "UI-EJ-BOSS-Princess Theradras",
            o = 8,
            s = {
                {
                    t = "Thrash",
                    b = "Princess Theradras thrashes, attacking 2 additional times.",
                    i = "Ability_GhoulFrenzy",
