        ["rotgrip"] = {
            d =
                "Rumor has it that Rotgrip has dwelled in Maraudon's subterranean waters for " ..
                "millennia. The famed dwarven hunter Hemet Nesingwary once proclaimed that " ..
                "the beast could not be found, and a number of amateur trackers accepted the " ..
