    [389] = {
        ["adarogg"] = {
            d =
                "Ragefire Chasm's trogg population has rapidly declined in recent months for " ..
                "one reason: Adarogg. This ravenous flame hound was among the first of his " ..
                "kind ripped from the Firelands by dark shaman. Adarogg's handlers feed the " ..
                "unruly beast over twice his weight in trogg flesh per day to keep him " ..
