        ["hydrospawn"] = {
            d =
                "When the satyr Zevrim Thornhoof sought to control the elementals in Dire " ..
                "Maul, he focused on Hydrospawn, who calmly resided in the pool beneath his " ..
                "altar. As he performed his profane sacrificial rituals, the elemental grew " ..
                "agitated and restless, striking out at Thornhoof's demonic minions. As the " ..
                "years passed, Thornhoof used his victims' energies to whip Hydrospawn into " ..
                "unbridled fury, little by little binding its will to the satyr's commands.",
