        ["illyannaravenoak"] = {
            d =
                "Illyanna Ravenoak, along with her faithful companion Ferra, was once Prince " ..
                "Tortheldrin's most valued hunter, until she refused to carry out her " ..
                "leader's order to execute her friends. As punishment, he killed Illyanna and " ..
                "her bear, but he used his demonic power to bind their spirits to their " ..
                "bodies, condemning them to remain in Dire Maul as undead protectors.",
            p = "UI-EJ-BOSS-Illyanna Ravenoak",
