        ["immolthar"] = {
            d =
                "In a desperate bid to restore the power and immortality they lost when the " ..
                "Well of Eternity was destroyed, the Shen'dralar summoned a demon into the " ..
                "western wing of Dire Maul and captured him within a force field, allowing " ..
                "them to use the void terror's energy for their own spells. Unable to fight " ..
                "back or even move for nearly 10,000 years, Immol'thar could only watch and " ..
                "wait for the day he might break free and rend the flesh of his captors.",
            p = "UI-EJ-BOSS-Immolthar",
            o = 8,
            s = {
