        ["kinggordok"] = {
            d =
                "To rule the Gordok ogres, one must simply proclaim oneself king... and then " ..
                "destroy all who might disagree. King Gordok--then merely known as " ..
                "Ulrok--solidified his power by convincing a dozen of his people's strongest " ..
                "warriors to challenge the king at the same time. The wild melee left most of " ..
                "the contestants dead or wounded, and Ulrok's blade easily cut down the " ..
                "survivors and the battle-weary king. To this day, Gordok ogres speak in " ..
                "hushed tones about the \"Day of Da Blood.\"",
            p = "UI-EJ-BOSS-King Gordok",
            o = 16,
            s = {
