        ["lethtendris"] = {
            d =
                "Dire Maul's warped energy drew Lethtendris from afar, giving her hope of " ..
                "satisfying her unbearable craving for arcane magic. Using the sinews and " ..
                "ligaments of sacrificial victims, she constructed a web to siphon the " ..
