        ["magisterkalendris"] = {
            d =
                "When Prince Tortheldrin demanded the slaughter of the majority of his " ..
                "subjects, his most loyal lieutenants were tasked with executing his will. " ..
                "Magister Kalendris murdered many unsuspecting Shen'dralar without " ..
                "hesitation, but one of the doomed elves mortally wounded him during a " ..
                "destructive battle. Despite his demise, Kalendris's spirit still roams Dire " ..
                "Maul as a defender of Tortheldrin's rule.",
            p = "UI-EJ-BOSS-Magister Kalendris",
            o = 7,
            s = {
