        ["princetortheldrin"] = {
            d =
                "After the Well of Eternity's destruction, Prince Tortheldrin maintained " ..
                "control over the surviving Shen'dralar by imprisoning a demon in the ruins " ..
                "of Eldre'Thalas and letting his subjects siphon its strength. The exposure " ..
                "to demonic power twisted Tortheldrin's mind, and when the creature faltered, " ..
                "the prince ordered the deaths of many of his vassals so only he and his most " ..
                "fanatical followers would be left to enjoy the corrupt energy.",
            p = "UI-EJ-BOSS-Prince Tortheldrin",
            o = 9,
