            },
        },
        ["stomperkreeg"] = {
            d =
                "On more than one occasion, skulking assassins have met their doom after " ..
                "accidentally disturbing Kreeg's ale mug. Though he's often passed out drunk " ..
                "on duty, nothing rouses the ogre into a berserker fury faster than the sound " ..
