        ["tendriswarpwood"] = {
            d =
                "Tendris Warpwood was a staunch defender of Eldre'Thalas, his heart " ..
                "inexorably entwined with the fate of the city. When the Sundering shattered " ..
                "the land, his resolve never wavered, but as corruption seeped into the ruins " ..
