        ["zevrimthornhoof"] = {
            d =
                "Desperate to show his worth to the Burning Legion, Zevrim Thornhoof told his " ..
                "masters he could enslave the formidable ancients who still roamed Dire Maul. " ..
                "When his own power proved insufficient, Thornhoof turned to other living " ..
                "creatures for additional energy, butchering them atop his sacrificial altar " ..
                "and harvesting their essence in their final, agonizing moments.",
            p = "UI-EJ-BOSS-Zevrim Thornhoof",
            o = 1,
            s = {
                {
                    t = "Intense Pain",
                    b =
