    [545] = {
        ["hydromancerthespia"] = {
            d =
                "At the height of the night elf empire, the Highborne Thespia delighted in " ..
                "art and music. Her love of these things vanished during the Great Sundering, " ..
                "when she and many of her kin were sucked into Azeroth's deeps and " ..
                "transformed into hateful naga. In the millennia that followed, Thespia " ..
                "remained a close confidant of her childhood friend, Lady Vashj. Without " ..
                "hesitation, she journeyed with her comrade to Zangarmarsh and vowed to " ..
                "oversee the naga's quest to drain the region's water supply.",
            p = "UI-EJ-BOSS-Hydromancer Thespia",
            o = 1,
            s = {
                {
                    t = "Enveloping Winds",
                    b = "Hydromancer Thespia surrounds a player with a cyclone, stunning them for 6 sec.",
                    i = "Spell_Nature_Cyclone",
                    f = 128,
                },
                {
                    t = "Lightning Cloud",
                    b =
                        "Hydromancer Thespia creates a cloud of lightning at a player's location that " ..
                        "lasts for 14 sec., inflicting 1575 to 2025 Nature damage every 2 seconds.",
                    i = "Spell_Nature_CallStorm",
                },
                {
                    t = "Lung Burst",
                    b =
                        "Hydromancer Thespia compresses a player's lungs, inflicting 602 to 698 " ..
                        "Physical damage every 2 sec for 10 sec.",
                    i = "Ability_Suffocate",
                    f = 128,
                },
                {
                    t = "Coilfang Water Elemental",
                    b = "Two Coilfang Water Elementals defend Hydromancer Thespia in battle.",
