                {
                    t = "Water Bolt Volley",
                    b =
                        "Coilfang Water Elementals hurl a volley of watery bolts at all nearby " ..
                        "players, inflicting 68 to 82 Frost damage.",
                    i = "Spell_Frost_Frostbolt",
                    f = 64,
                    l = 1,
                },
            },
        },
        ["mekgineersteamrigger"] = {
            d =
                "The irradiation of Gnomeregan transformed many of the city's survivors into " ..
                "leper gnomes. Among these victims was the brilliant Mekgineer Steamrigger. " ..
                "Although he escaped Gnomeregan and retained his intellect, whatever ethics " ..
                "and compassion he had once possessed were gone. He wandered Azeroth, selling " ..
                "his knowledge to a number of unscrupulous groups such as the Bloodsail " ..
                "Buccaneers. Recently, the naga hired Steamrigger to operate the intricate " ..
                "machinery in Zangarmarsh's Steamvault.",
            p = "UI-EJ-BOSS-Mekgineer Steamrigger",
            o = 2,
            s = {
                {
                    t = "Electrified Net",
                    b =
                        "Mekgineer Steamrigger immobilizes a player in an electrified net, inflicting " ..
                        "602 to 698 Nature damage every 2 sec. for 6 sec.",
                    i = "Ability_Ensnare",
