                        "Physical damage.",
                    i = "INV-Sword_53",
                },
                {
                    t = "Steamrigger Mechanics",
                    b =
                        "When Mekgineer Steamrigger reaches 75%, 50% and 25% remaining health, he " ..
                        "summons Steamrigger Mechanics to repair him.",
                },
                {
                    t = "Repair",
                    b =
                        "Steamrigger Mechanics repair Mekgineer Steamrigger, healing him for 1050 " ..
