    [546] = {
        ["ghazan"] = {
            d =
                "Historians have long disagreed about whether the immense hydras of Azeroth " ..
                "and Outland share a common ancestor. What is clear, however, is that these " ..
                "ruthless creatures have existed on both realms since ancient times. Ghaz'an " ..
                "is one of the most infamous and fearsome hydras on Outland. Under the " ..
                "control of Lady Vashj, this ravenous fiend has stormed the lower reaches of " ..
                "Zangarmarsh to terrorize the region's denizens.",
            p = "UI-EJ-BOSS-Ghazan",
            o = 2,
            s = {
                {
