        ["murmur"] = {
            d =
                "\"In the beginning\"... \"So far away\"... such phrases cannot begin to describe " ..
                "this elemental's origin. Its existence heralds pure destruction. Worlds " ..
                "shatter and the pieces scatter at its whim. Only the truly mad would think " ..
